// The scraper sends an array of leads. Split into individual items.
// Normalize field names for downstream processing.
const body = $input.first().json.body || $input.first().json;
const leads = Array.isArray(body) ? body : [body];

return leads.map(lead => ({
  json: {
    // Contact info
    phone: (lead.phone || '').replace(/[^\d]/g, ''),
    email: lead.email || null,
    name: lead.name || lead.pushName || null,
    message: lead.message || '',
    // Property info (already available from scraper)
    listing_id: lead.listing_id || null,
    property_title: lead.property || lead.address || 'Propiedad sin titulo',
    property_address: lead.address || '',
    property_price: lead.price || 'Precio por confirmar',
    listing_type: lead.listing_type || 'venta',
    // Scraper metadata
    scraper_lead_id: lead.lead_id || null,
    source_tab: lead.source_tab || 'mensajes',
    source: 'inmuebles24'
  }
}));

// Route decision based on returning lead check and day/night.
const lead = $('Split & Normalize Leads').item.json;
const db = $input.first().json;

// If no phone, skip this lead
if (!lead.phone) {
  return [{ json: { route: 'skip', reason: 'no_phone' } }];
}

const isReturning = !!db.existing_conv_id;
const sameProperty = db.same_property === true;
const isDay = db.is_day !== false; // Default to day if query returns no rows

if (isReturning && sameProperty) {
  return [{
    json: {
      route: 'returning_same',
      existing_conv_id: db.existing_conv_id,
      assigned_agent_id: db.assigned_agent_id,
      existing_mode: db.existing_mode,
      ...lead
    }
  }];
}

if (isDay) {
  return [{
    json: {
      route: 'day_auction',
      is_returning_diff: isReturning && !sameProperty,
      ...lead
    }
  }];
}

return [{
  json: {
    route: 'night_queue',
    is_returning_diff: isReturning && !sameProperty,
    ...lead
  }
}];

// Notify the assigned agent about a returning lead (same property).
const data = $('Route Decision').first().json;
const conv = $input.first().json;

if (!data.assigned_agent_id) {
  return [{ json: { skip: true, reason: 'no_assigned_agent' } }];
}

return [{
  json: {
    number: data.assigned_agent_id, // Will be resolved to phone below
    conversation_id: data.existing_conv_id,
    lead_name: data.name,
    lead_phone: data.phone,
    property_title: data.property_title,
    message: `Lead recurrente: ${data.name || data.phone} volvio a preguntar por ${data.property_title}. Ya lo tienes asignado.`
  }
}];

// Prepare data for WF3a auction call.
const lead = $('Route Decision').first().json;
const conv = $input.first().json;

// Build cache payload from scraper data
const cachePayload = {
  title: lead.property_title,
  price: lead.property_price,
  location: lead.property_address,
  operation_type: lead.listing_type,
  source: 'inmuebles24_scraper'
};

return [{
  json: {
    // For WF3a
    conversation_id: conv.conversation_id,
    lead_phone: conv.lead_phone,
    lead_name: conv.lead_name || lead.name,
    property_id: lead.listing_id || 'unknown',
    property_title: lead.property_title,
    property_price: lead.property_price,
    assigned_agent_id: null,
    // For caching
    cache_property_id: lead.listing_id || 'unknown',
    cache_payload: cachePayload
  }
}];

